output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles, where there is only one free cell of horizontal clearance.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_entering_single_file_with_cart",
    "text": "A shopper pushing a cart is forbidden from moving into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "no_cart_shelf_service_in_single_file",
    "text": "Shelf interactions inside a single-file aisle must be performed without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "shelfServiceInSingleFile": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelfServiceInSingleFile",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_returning_from_narrow_aisle",
    "text": "After returning from a cart-free single-file aisle to its mouth, the shopper must retrieve the cart before continuing.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "narrowAisleMouth": "at(3,3)",
        "atMouthWithoutCart": {
          "and": [
            "narrowAisleMouth",
            "noCart"
          ]
        }
      },
      "events": {
        "returnToMouthWithoutCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "noCart",
              "S"
            ]
          },
          "post": "atMouthWithoutCart"
        },
        "pickupCartAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "noCart",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnToMouthWithoutCart",
      "discharge": "pickupCartAtMouth"
    }
  },
  {
    "id": "return_to_cart_mouth_after_narrow_item",
    "text": "After collecting an item from a single-file shelf aisle without a cart, the shopper must return to the aisle mouth where the cart was left.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "narrowAisleMouth": "at(3,3)",
        "atMouthWithoutCart": {
          "and": [
            "narrowAisleMouth",
            "noCart"
          ]
        }
      },
      "events": {
        "takeNarrowAisleItemWithoutCart": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileShelfAisle",
              "noCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "takeNarrowAisleItemWithoutCart",
      "discharge": "atMouthWithoutCart"
    }
  },
  {
    "id": "cart_transfers_only_at_parking_points",
    "text": "Carts may only be picked up or put down at designated cart-parking points such as the entrance cart station or the mouth of a narrow aisle.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        },
        "cartStation": "at(1,7)",
        "narrowAisleMouth": "at(3,3)",
        "cartParkingPoint": {
          "or": [
            "cartStation",
            "narrowAisleMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": "noCart"
        },
        "pickupCart": {
          "pre": {
            "and": [
              "noCart",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "dropCart",
              "pickupCart"
            ]
          },
          {
            "not": "cartParkingPoint"
          }
        ]
      }
    }
  },
  {
    "id": "no_roaming_open_aisles_without_cart",
    "text": "Except at the entrance/cart station or a narrow-aisle parking mouth, shoppers should not move through wide open aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "wideOpenAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "cartStationArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "narrowAisleMouth": "at(3,3)",
        "allowedCartlessWideArea": {
          "or": [
            "cartStationArea",
            "narrowAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "wideOpenAisle",
          "MOVE",
          {
            "not": "allowedCartlessWideArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_broad_shelf_faces",
    "text": "When interacting with a shelf from a broad aisle face rather than a single-file aisle, the shopper must have a cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "broadShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFile"
            }
          ]
        }
      },
      "events": {
        "broadShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "broadShelfFace"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "broadShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
